$envPath = "C:\Users\CaveUser\Documents\Obsidian Vault\My_Data\.env"

# Parse .env and check key presence (names + length only, no values)
Get-Content $envPath | Where-Object { $_ -match '^[A-Z_]+=' -and $_ -notmatch '^\s*#' } | ForEach-Object {
  $line = $_
  $name = ($line -split '=', 2)[0].Trim()
  $value = ($line -split '=', 2)[1]
  if ($value) {
    $value = $value.Trim().Trim('"').Trim("'")
  }
  $hasValue = $value -and $value.Length -gt 0
  $len = if ($hasValue) { $value.Length } else { 0 }
  [PSCustomObject]@{ Name = $name; Set = $hasValue; Length = $len }
} | Where-Object {
  $_.Name -match 'FEC|CONGRESS|OPENSTATES|OPENSECRETS|DATA_GOV'
} | Format-Table -AutoSize

$envPath = "C:\Users\CaveUser\Documents\Obsidian Vault\My_Data\.env"

# Load keys from .env (in-process only)
$envMap = @{}
Get-Content $envPath | Where-Object { $_ -match '^[A-Z_]+=' -and $_ -notmatch '^\s*#' } | ForEach-Object {
  $parts = $_ -split '=', 2
  $envMap[$parts[0].Trim()] = $parts[1].Trim().Trim('"').Trim("'")
}

function Test-Endpoint {
  param([string]$Name, [string]$Url, [hashtable]$Headers = @{})
  $start = Get-Date
  try {
    $resp = Invoke-RestMethod -Uri $Url -Headers $Headers -TimeoutSec 15 -ErrorAction Stop
    $elapsed = [int]((Get-Date) - $start).TotalMilliseconds
    # Try to infer record count from common shapes
    $count = if ($resp.results) { $resp.results.Count } elseif ($resp.bills) { $resp.bills.Count } elseif ($resp.bill) { 1 } else { 'n/a' }
    [PSCustomObject]@{ API = $Name; Status = 'OK'; Latency_ms = $elapsed; Records = $count; Note = '' }
  } catch {
    $code = $_.Exception.Response.StatusCode.value__
    $msg = $_.Exception.Message
    if ($msg.Length -gt 80) { $msg = $msg.Substring(0,80) + '...' }
    [PSCustomObject]@{ API = $Name; Status = "FAIL ($code)"; Latency_ms = 0; Records = 0; Note = $msg }
  }
}

$results = @()

# 1. FEC API
$fecKey = $envMap['FEC_API_KEY']
$results += Test-Endpoint -Name 'FEC' -Url "https://api.open.fec.gov/v1/candidates/?api_key=$fecKey&per_page=1&sort=-receipts"

# 2. Congress.gov API
$congressKey = $envMap['CONGRESS_API_KEY']
$results += Test-Endpoint -Name 'Congress.gov' -Url "https://api.congress.gov/v3/bill?api_key=$congressKey&limit=1&format=json"

# 3. OpenStates API (uses header auth)
$osKey = $envMap['OPENSTATES_API_KEY']
$results += Test-Endpoint -Name 'OpenStates' -Url "https://v3.openstates.org/bills?per_page=1&jurisdiction=ocd-jurisdiction/country:us/state:ca/government" -Headers @{ 'X-API-Key' = $osKey }

# 4. OpenSecrets (note: not wired yet)
if ($envMap['OPENSECRETS_API_KEY']) {
  $osecKey = $envMap['OPENSECRETS_API_KEY']
  $results += Test-Endpoint -Name 'OpenSecrets' -Url "https://www.opensecrets.org/api/?method=getLegislators&id=NJ&apikey=$osecKey&output=json"
} else {
  $results += [PSCustomObject]@{ API = 'OpenSecrets'; Status = 'NOT SET'; Latency_ms = 0; Records = 0; Note = 'Awaiting application approval' }
}

$results | Format-Table -AutoSize | Out-String -Width 200

$envPath = "C:\Users\CaveUser\Documents\Obsidian Vault\My_Data\.env"
$envMap = @{}
Get-Content $envPath | Where-Object { $_ -match '^[A-Z_]+=' -and $_ -notmatch '^\s*#' } | ForEach-Object {
  $parts = $_ -split '=', 2
  $envMap[$parts[0].Trim()] = $parts[1].Trim().Trim('"').Trim("'")
}
$fecKey = $envMap['FEC_API_KEY']

# Retry without invalid sort param
$start = Get-Date
try {
  $resp = Invoke-RestMethod -Uri "https://api.open.fec.gov/v1/candidates/?api_key=$fecKey&per_page=1&cycle=2026" -TimeoutSec 15
  $elapsed = [int]((Get-Date) - $start).TotalMilliseconds
  $count = $resp.results.Count
  $total = $resp.pagination.count
  Write-Output "FEC: OK ($elapsed ms) — 1 candidate returned out of $total total in 2026 cycle"
  Write-Output "Sample name: $($resp.results[0].name)"
} catch {
  Write-Output "FEC still failing: $($_.Exception.Message)"
}

# Also check rate-limit headers (api.data.gov returns these)
Write-Output ""
Write-Output "=== Checking rate-limit headers ==="
try {
  $resp = Invoke-WebRequest -Uri "https://api.open.fec.gov/v1/candidates/?api_key=$fecKey&per_page=1&cycle=2026" -TimeoutSec 15
  $resp.Headers.GetEnumerator() | Where-Object { $_.Key -match 'RateLimit|X-RateLimit' } | ForEach-Object { "$($_.Key): $($_.Value)" }
} catch {
  Write-Output "Headers check failed: $($_.Exception.Message)"
}

$envPath = "C:\Users\CaveUser\Documents\Obsidian Vault\My_Data\.env"
$envMap = @{}
Get-Content $envPath | Where-Object { $_ -match '^[A-Z_]+=' -and $_ -notmatch '^\s*#' } | ForEach-Object {
  $parts = $_ -split '=', 2
  $envMap[$parts[0].Trim()] = $parts[1].Trim().Trim('"').Trim("'")
}
$fecKey = $envMap['FEC_API_KEY']
$congressKey = $envMap['CONGRESS_API_KEY']
$osKey = $envMap['OPENSTATES_API_KEY']

# ===== FEC: defense/tech/housing corporate PACs =====
Write-Output "===================="
Write-Output "FEC — Corporate PAC Lookups"
Write-Output "===================="
foreach ($name in @('LOCKHEED MARTIN','RAYTHEON','MICROSOFT','GOOGLE','D.R. HORTON','BLACKROCK')) {
  $encoded = [Uri]::EscapeDataString($name)
  try {
    $r = Invoke-RestMethod -Uri "https://api.open.fec.gov/v1/committees/?api_key=$fecKey&q=$encoded&per_page=1" -TimeoutSec 15
    if ($r.results.Count -gt 0) {
      $c = $r.results[0]
      "{0,-22} → {1} | type {2} | designation {3} | ID {4}" -f $name, $c.name, $c.committee_type, $c.designation, $c.committee_id
    } else {
      "{0,-22} → (no matches)" -f $name
    }
  } catch {
    "{0,-22} → ERROR: {1}" -f $name, $_.Exception.Message
  }
}

# ===== Congress.gov: recent bills (filter for sector keywords client-side) =====
Write-Output ""
Write-Output "===================="
Write-Output "Congress.gov — Recent 119th-Congress Bills (filtered)"
Write-Output "===================="
try {
  $r = Invoke-RestMethod -Uri "https://api.congress.gov/v3/bill/119?api_key=$congressKey&limit=50&format=json&sort=updateDate+desc" -TimeoutSec 20
  $keywords = @{
    housing = @('hous','rental','mortgage','tenant','zoning','homeless','LIHTC','FHA','GSE')
    defense = @('defense','NDAA','military','veteran','armed services','DoD','arms')
    tech    = @('artificial intelligence',' AI ','antitrust','privacy','data','semiconductor','broadband')
  }
  foreach ($sector in $keywords.Keys) {
    $matched = $r.bills | Where-Object {
      $title = $_.title
      ($keywords[$sector] | Where-Object { $title -match $_ }).Count -gt 0
    } | Select-Object -First 3
    Write-Output "--- ${sector} ---"
    if ($matched.Count -eq 0) { Write-Output "  (no matches in latest 50)" }
    foreach ($b in $matched) {
      $title = $b.title
      if ($title.Length -gt 100) { $title = $title.Substring(0,100) + '...' }
      "  $($b.type)-$($b.number): $title  [updated $($b.updateDate)]"
    }
  }
  Write-Output ""
  Write-Output "Total returned: $($r.bills.Count) / total in pagination: $($r.pagination.count)"
} catch {
  Write-Output "ERROR: $($_.Exception.Message)"
}

# ===== OpenStates: sector keyword search in CA + TX =====
Write-Output ""
Write-Output "===================="
Write-Output "OpenStates — Keyword Search (CA + TX)"
Write-Output "===================="
$queries = @(
  @{ state='ca'; q='housing affordability'; sector='Housing' },
  @{ state='ca'; q='artificial intelligence'; sector='Tech' },
  @{ state='tx'; q='defense industry'; sector='Defense' }
)
foreach ($q in $queries) {
  $url = "https://v3.openstates.org/bills?q=$([Uri]::EscapeDataString($q.q))&jurisdiction=ocd-jurisdiction/country:us/state:$($q.state)/government&per_page=2&sort=updated_desc"
  try {
    $r = Invoke-RestMethod -Uri $url -Headers @{ 'X-API-Key' = $osKey } -TimeoutSec 20
    Write-Output "--- $($q.state.ToUpper()) / $($q.sector) / q='$($q.q)' ---"
    if ($r.results.Count -eq 0) { Write-Output "  (no matches)" }
    foreach ($b in $r.results) {
      $title = $b.title
      if ($title.Length -gt 90) { $title = $title.Substring(0,90) + '...' }
      "  $($b.identifier): $title  [updated $($b.updated_at.Substring(0,10))]"
    }
  } catch {
    "  ERROR for $($q.state)/$($q.q): $($_.Exception.Message)"
  }
}

$envPath = "C:\Users\CaveUser\Documents\Obsidian Vault\My_Data\.env"
$envMap = @{}
Get-Content $envPath | Where-Object { $_ -match '^[A-Z_]+=' -and $_ -notmatch '^\s*#' } | ForEach-Object {
  $parts = $_ -split '=', 2; $envMap[$parts[0].Trim()] = $parts[1].Trim().Trim('"').Trim("'")
}
$congressKey = $envMap['CONGRESS_API_KEY']
$osKey = $envMap['OPENSTATES_API_KEY']

$outDir = "C:\Users\CaveUser\Documents\Obsidian Vault\My_Data\scripts\policy\_fetched"
New-Item -ItemType Directory -Force -Path $outDir | Out-Null

# ----- Federal bills via Congress.gov -----
$federal = @(
  @{ congress=119; type='hr'; number=8479; label='HR-8479' },
  @{ congress=119; type='s';  number=4459; label='S-4459' },
  @{ congress=119; type='s';  number=4424; label='S-4424' }
)
foreach ($b in $federal) {
  $url = "https://api.congress.gov/v3/bill/$($b.congress)/$($b.type)/$($b.number)?api_key=$congressKey&format=json"
  try {
    $r = Invoke-RestMethod -Uri $url -TimeoutSec 20
    $b.detail = $r.bill
    # Also fetch text & summary if available
    $sumUrl = "https://api.congress.gov/v3/bill/$($b.congress)/$($b.type)/$($b.number)/summaries?api_key=$congressKey&format=json"
    try { $s = Invoke-RestMethod -Uri $sumUrl -TimeoutSec 15; $b.summaries = $s.summaries } catch { $b.summaries = @() }
    $r | ConvertTo-Json -Depth 12 | Out-File -FilePath "$outDir\$($b.label).json" -Encoding UTF8
    Write-Output "✓ $($b.label) → $($r.bill.title.Substring(0,[Math]::Min(80,$r.bill.title.Length)))"
  } catch { Write-Output "✗ $($b.label) ERROR: $($_.Exception.Message)" }
}

# ----- CA state bills via OpenStates -----
$ca = @(
  @{ identifier='AB 736'; label='CA-AB-736' },
  @{ identifier='SB 903'; label='CA-SB-903' },
  @{ identifier='AB 412'; label='CA-AB-412' }
)
foreach ($b in $ca) {
  $q = [Uri]::EscapeDataString($b.identifier)
  $url = "https://v3.openstates.org/bills?jurisdiction=ocd-jurisdiction/country:us/state:ca/government&q=$q&per_page=5&sort=updated_desc&include=sponsorships&include=abstracts&include=actions"
  try {
    $r = Invoke-RestMethod -Uri $url -Headers @{ 'X-API-Key' = $osKey } -TimeoutSec 20
    # Find the right session (current 2025-2026 regular session — typically the one with most recent updated_at)
    $match = $r.results | Where-Object { $_.identifier -eq $b.identifier } | Sort-Object updated_at -Descending | Select-Object -First 1
    if (-not $match) { $match = $r.results[0] }
    $b.detail = $match
    $match | ConvertTo-Json -Depth 12 | Out-File -FilePath "$outDir\$($b.label).json" -Encoding UTF8
    $title = $match.title; if ($title.Length -gt 80) { $title = $title.Substring(0,80) }
    Write-Output "✓ $($b.label) ($($match.session)) → $title"
  } catch { Write-Output "✗ $($b.label) ERROR: $($_.Exception.Message)" }
}

Write-Output ""
Write-Output "JSON saved to: $outDir"
(Get-ChildItem $outDir -Filter *.json | Measure-Object).Count
"files"
